fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo = 0;
    let mut hi = v.len();
    while lo < hi {
        // mid is always in range [lo, hi), so < v.len()
        let mid = lo + (hi - lo) / 2;
        let val = v[mid];
        if val < k {
            lo = mid + 1;
        } else if val > k {
            hi = mid;
        } else {
            // Found an occurrence of k
            return mid;
        }
    }
    // Since k is guaranteed to be in v, lo == hi < v.len() and v[lo] == k
    lo
}